    "Over een uur is het al morgen. De zaak van vandaag staat nog klaar.": "Через час уже наступит завтра. Дело на сегодня всё ещё ждёт.",
    "De dossiers wachten op je. Ik stuur je geen herinneringen meer.": "Дела подождут вас. Я больше не буду присылать напоминания.",
    "De zaak van vandaag heet “{0}”. Een paar minuten, meer vraag ik niet.": "Дело на сегодня называется «{0}». Несколько минут — больше я не прошу.",
    "Nieuw dossier: “{0}”. Plaats delict: {1}.": "Новое дело: «{0}». Место преступления: {1}.",
    "“{0}” ligt klaar. Een handvol verdachten, één waarheid. Kijk je even mee?": "Дело «{0}» готово. Горстка подозреваемых, одна правда. Заглянете?",
    "De koffie staat klaar, het dossier ook: “{0}”.": "Кофе готов, папка с делом тоже: «{0}».",
    "Ik heb een zaak voor je: “{0}”. De vraag is kort: wie was waar?": "У меня для вас дело: «{0}». Вопрос короткий: кто где был?",
    "{0} · “{1}”. Ik ben benieuwd wat jij ziet.": "{0} · «{1}». Любопытно, что вы заметите.",
    "Het archief loopt niet weg. Vandaag ligt “{0}” klaar, als je zin hebt.": "Архив никуда не денется. Сегодня вас ждёт «{0}», если будет настроение.",
    "Een rustige dag op het bureau. “{0}” wacht geduldig op een frisse blik.": "Спокойный день в участке. «{0}» терпеливо ждёт свежего взгляда.",
    "Geen haast. Als het uitkomt: “{0}” ligt bovenop de stapel.": "Спешить некуда. Когда будет удобно: «{0}» лежит на самом верху стопки.",
    "Ik heb je dossierkast netjes bijgehouden. Bovenop vandaag: “{0}”.": "Я навёл порядок в вашей картотеке. Сегодня сверху: «{0}».",
    "Voor een kort moment tussendoor: “{0}”. Drie minuten en een kop thee.": "Для короткой паузы: «{0}». Три минуты и чашка чая.",
    "Je streak staat op {0} dagen. De zaak van vandaag ligt nog open: “{1}”.": "Ваша серия: {0} {0|one:день|few:дня|many:дней|other:дня} подряд. Дело на сегодня ещё открыто: «{1}».",
    "{0} dagen op rij. Eén zaak vanavond en het worden er {1}.": "{0} {0|one:день|few:дня|many:дней|other:дня} подряд. Одно дело сегодня вечером — и станет {1}.",
    "Nog een kort verhoor voor het slapengaan? “{0}” houdt je streak van {1} dagen heel.": "Ещё один короткий допрос перед сном? «{0}» сохранит вашу серию из {1} {1|one:дня|few:дней|many:дней|other:дня}.",
    "🔥 {0} dagen. Het vuur brandt nog; één zaak houdt het aan.": "🔥 {0} {0|one:день|few:дня|many:дней|other:дня}. Огонь ещё горит; одно дело не даст ему погаснуть.",
    "Om middernacht sluit het dossier van vandaag. Tijd genoeg voor “{0}” en dag {1} van je streak.": "В полночь дело на сегодня закрывается. Времени хватит и на «{0}», и на {1}-й день серии.",
    "Rustig avondwerk: “{0}”. Daarmee komt je streak op {1} dagen.": "Спокойная вечерняя работа: «{0}». Так ваша серия дойдёт до {1} {1|one:дня|few:дней|many:дней|other:дня}.",
    "Het uur is om. “{0}” ligt nog op je bureau.": "Час прошёл. «{0}» всё ещё у вас на столе.",
    "Zoals afgesproken: “{0}”. Daarna laat ik je met rust.": "Как договаривались: «{0}». После этого я оставлю вас в покое.",
    "Een uur later, zelfde dossier: “{0}”. Je streak van {1} dagen wacht.": "Час спустя, то же дело: «{0}». Ваша серия из {1} {1|one:дня|few:дней|many:дней|other:дня} ждёт.",
    "Hier ben ik weer. Eén zaak, en je streak gaat naar {0} dagen.": "Это снова я. Одно дело — и ваша серия вырастет до {0} {0|one:дня|few:дней|many:дней|other:дня}.",
    "Afspraak is afspraak: “{0}”, nog vóór middernacht.": "Уговор есть уговор: «{0}», до полуночи.",
    "🔍 Live Activity tijdens een zaak": "🔍 Live Activity во время дела",
